        groups[key] = []
    groups[key].append(e)
for norm, entries in groups.items():
    print(f'=== {norm} ({len(entries)} entries) ===')
    for e in entries[:3]:
        print(f'  id={e[\"entry_id\"]} hw={e[\"headword\"]} root={e.get(\"root\")} src={e[\"source_type\"]} period={e.get(\"period\")}')
        defn = (e.get('definitions_text') or '')[:150]
        if defn: print(f'    def: {defn}')
        tr = e.get('translation_en')
        if tr: print(f'    en: {tr}')
    if len(entries) > 3:
        print(f'  ... and {len(entries)-3} more')
